using System;using System.IO;using System.Drawing;using System.Drawing.Imaging;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Runtime.InteropServices;using Newtonsoft.Json.Linq;using LibreHardwareMonitor.Hardware;
namespace JonsboStudio {
 static class Program {
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool SetDllDirectory(string path);
  [STAThread]static int Main(string[] args){try{SetDllDirectory(AppPaths.Root);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
   if(args.Length>0){
    if(args[0]=="--self-test"){SelfTest();return 0;}
    if(args[0]=="--sensors"){using(var sampler=new SensorSampler()){Thread.Sleep(1200);Console.WriteLine(Newtonsoft.Json.JsonConvert.SerializeObject(sampler.Latest.values));Thread.Sleep(1200);Console.WriteLine(Newtonsoft.Json.JsonConvert.SerializeObject(sampler.Latest.values));}return 0;}
    if(args[0]=="--gpu-sensors"){var computer=new Computer{IsGpuEnabled=true};computer.Open();try{foreach(var hardware in computer.Hardware)if(hardware.HardwareType.ToString().StartsWith("Gpu",StringComparison.OrdinalIgnoreCase)){hardware.Update();Console.WriteLine(hardware.Name);foreach(var sensor in hardware.Sensors)if(sensor.Value.HasValue)Console.WriteLine(sensor.SensorType+" / "+sensor.Name+" = "+sensor.Value.Value);}}finally{computer.Close();}return 0;}
    if(args[0]=="--render-frame"){var theme=ThemeDocument.Load(args[1]);var config=new StudioSettings{Width=theme.Width,Height=theme.Height,Fps=60,Quality=75,CacheMB=64};using(var engine=new PlaybackEngine(theme,config,false)){engine.Start();var timer=Stopwatch.StartNew();while(engine.Latest==null&&engine.Error.Length==0&&timer.ElapsedMilliseconds<30000)Thread.Sleep(20);if(engine.Latest==null)throw new Exception(engine.Error.Length>0?engine.Error:"No rendered frame was produced.");Thread.Sleep(1200);File.WriteAllBytes(args[2],engine.Latest.jpeg);Console.WriteLine("Rendered "+theme.Name+": "+theme.Texts.Count+" text, "+theme.Images.Count+" image layers; "+theme.Width+"x"+theme.Height+"; "+engine.Error);}return 0;}
    if(args[0]=="--list-devices"){Console.WriteLine(Newtonsoft.Json.JsonConvert.SerializeObject(JonsboTransport.Discover(),Newtonsoft.Json.Formatting.Indented));return 0;}
    if(args[0]=="--import-theme"){Console.WriteLine(ThemeRepository.Import(args[1]));return 0;}
    if(args[0]=="--export-theme"){ThemeRepository.Export(args[1],args[2]);Console.WriteLine("Exported native theme.");return 0;}
    if(args[0]=="--ui-test"||args[0]=="--ui-benchmark"){Exception failure=null;using(var form=new AppForm(false,false)){form.Shown+=async(s,e)=>{try{if(args[0]=="--ui-test")await form.UiSmoke();else Console.WriteLine(await form.UiBenchmark(args[1],args.Length>2?args[2]:""));}catch(Exception ex){failure=ex;}await form.Exit();};Application.Run(form);}if(failure!=null)throw failure;return 0;}
    if(args[0]=="--multi-benchmark"){Exception failure=null;using(var form=new AppForm(false,false)){form.Shown+=async(s,e)=>{try{Console.WriteLine(await form.MultiDeviceBenchmark(args[1],args[2]));}catch(Exception ex){failure=ex;}await form.Exit();};Application.Run(form);}if(failure!=null)throw failure;return 0;}
    if(args[0]=="--query-device"){using(var display=new JonsboTransport()){display.Connect(args[1]);Console.WriteLine(display.SerialNumber+" · "+display.NativeWidth+"×"+display.NativeHeight);}return 0;}
    if(args[0]=="--benchmark"){var theme=ThemeDocument.Load(args[1]);var config=new StudioSettings{Width=theme.Width,Height=theme.Height,Fps=60,Quality=75,CacheMB=128,Port=args.Length>2?args[2]:""};bool hardware=args.Length>2;var process=Process.GetCurrentProcess();using(var engine=new PlaybackEngine(theme,config,hardware)){engine.Start();var wait=Stopwatch.StartNew();while(engine.Latest==null&&engine.Error.Length==0&&wait.ElapsedMilliseconds<30000)Thread.Sleep(20);if(engine.Latest==null)throw new Exception(engine.Error);wait.Restart();while(!engine.PreparedComplete&&engine.Error.Length==0&&wait.ElapsedMilliseconds<20000)Thread.Sleep(50);long first=engine.Produced,sent=engine.Sent;var cpu=process.TotalProcessorTime;wait.Restart();Thread.Sleep(5000);double seconds=wait.Elapsed.TotalSeconds;process.Refresh();Console.WriteLine("Render={0:F2} FPS; sent={1:F2} FPS; host_cpu={2:F2}% of {3} logical CPUs; RAM={4:F1}MB; cache={5}/{6} {7}; cacheRAM={8:F1}MB; disk={9:F1}MB; encode={10:F2}ms; transfer={11:F2}ms; rotation={12}; error={13}",(engine.Produced-first)/seconds,(engine.Sent-sent)/seconds,100*(process.TotalProcessorTime-cpu).TotalSeconds/seconds/Environment.ProcessorCount,Environment.ProcessorCount,process.WorkingSet64/1048576.0,engine.Prepared,engine.ExpectedFrames,engine.PreparedComplete?"ready":"preparing",engine.RamMB,engine.DiskMB,engine.EncodeMs,engine.TransferMs,engine.Rotation,engine.Error);if(engine.Error.Length>0)throw new Exception(engine.Error);}return 0;}
    if(args[0]=="--screenshot"){Exception failure=null;using(var form=new AppForm(false,false)){form.Shown+=async(s,e)=>{try{await form.CaptureScreenshot(Path.GetFullPath(args[1]),args.Length>2?args[2]:"display",args.Length>3?args[3]:null);}catch(Exception ex){failure=ex;}await form.Exit();};Application.Run(form);}if(failure!=null)throw failure;return 0;}
    if(args[0]=="--exit"){using(var signal=EventWaitHandle.OpenExisting("Local\\JonsboStudio.Exit"))signal.Set();return 0;}
   }
   using(var mutex=new Mutex(false,"Local\\JonsboStudio.Instance")){bool owned;try{owned=mutex.WaitOne(0);}catch(AbandonedMutexException){owned=true;}if(!owned){using(var signal=EventWaitHandle.OpenExisting("Local\\JonsboStudio.Show"))signal.Set();return 0;}try{using(var show=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\JonsboStudio.Show"))using(var exit=new EventWaitHandle(false,EventResetMode.AutoReset,"Local\\JonsboStudio.Exit"))using(var form=new AppForm()){
     IntPtr handle=form.Handle;var showWait=ThreadPool.RegisterWaitForSingleObject(show,(s,t)=>{try{form.BeginInvoke(new Action(form.Restore));}catch{}},null,Timeout.Infinite,false);var exitWait=ThreadPool.RegisterWaitForSingleObject(exit,(s,t)=>{try{form.BeginInvoke(new Action(async()=>await form.Exit()));}catch{}},null,Timeout.Infinite,false);if(args.Length>0&&args[0]=="--background")form.Shown+=(s,e)=>{form.Hide();form.ShowInTaskbar=false;};try{Application.Run(form);}finally{showWait.Unregister(null);exitWait.Unregister(null);}
    }}finally{mutex.ReleaseMutex();}}
   return 0;
  }catch(Exception ex){Console.Error.WriteLine(ex);if(args.Length==0)MessageBox.Show(ex.Message,"JONSBO Studio");return 1;}}
  static void Assert(bool value,string message){if(!value)throw new Exception("FAIL: "+message);}
  static void SelfTest(){string folder=Path.Combine(AppPaths.Data("Temp"),"test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string imported=null;try{
   Assert(ThemeDocument.BoundSuffix(new JObject{{"TextType","GpuFrequency"},{"Text","MHz"}})=="MHz","bound text suffix survives legacy editor input");Assert(ThemeDocument.BoundSuffix(new JObject{{"TextType","GpuFrequency"},{"Text","802"}})=="","stale native sample is not appended");Assert(ThemeDocument.BoundSuffix(new JObject{{"TextType","GpuFrequency"},{"Text","802"},{"Unit"," MHz"}})==" MHz","explicit unit is appended");var live=new SensorSnapshot();live.values["GPUTemp"]="41";live.values["GpuFrequency"]="1500";Assert(ThemeDocument.BoundValue(new JObject{{"TextType","GPUTemp"},{"Unit"," °F"}},live)=="106 °F","GPU Fahrenheit uses conversion");Assert(ThemeDocument.BoundValue(new JObject{{"TextType","GPUTemp"},{"Unit"," °C"}},live)=="41 °C","GPU Celsius remains live value");Assert(ThemeDocument.BoundValue(new JObject{{"TextType","GpuFrequency"},{"Unit"," GHz"}},live)=="1.50 GHz","GPU clock unit converts to GHz");Assert(ThemeDocument.BoundSuffix(new JObject{{"TextType","GpuFrequency"},{"Text","MHz"},{"Unit",""}})=="","No unit overrides legacy suffix");
   string image=Path.Combine(folder,"back.png");using(var bitmap=new Bitmap(320,100)){using(var graphics=Graphics.FromImage(bitmap)){graphics.Clear(Color.Navy);graphics.FillRectangle(Brushes.Red,0,0,160,100);}bitmap.Save(image,ImageFormat.Png);using(var codec=new TurboCodec()){var jpeg=codec.Encode(bitmap,80);using(var decoded=new Bitmap(320,100,PixelFormat.Format24bppRgb)){codec.Decode(jpeg,decoded);Assert(decoded.GetPixel(30,30).R>180,"TurboJPEG preserves color");}}}
   var json=ThemeDocument.Blank("Roundtrip",320,100);json["BackgroundImage"]=image;json["UnknownVendorField"]=new JObject{{"preserve",true}};json["DisplayTexts"]=new JArray(new JObject{{"Id","sample"},{"TextType","DIYTextList"},{"Text","JONSBO"},{"Left",170},{"Top",20},{"FontSize",24},{"Color","White"},{"FontName","Segoe UI"}});string path=Path.Combine(folder,"Roundtrip.json");AppPaths.SaveJson(path,json);string archive=Path.Combine(folder,"Roundtrip.vmax");ThemeRepository.Export(path,archive);imported=ThemeRepository.Import(archive);var theme=ThemeDocument.Load(imported);Assert(theme.BackgroundFit=="cover","new themes default to screen-cover mode");theme.Json["BackgroundFit"]="contain";theme.UseCover();Assert(theme.BackgroundFit=="cover"&&((string)theme.ForEditor()["BackgroundFit"])=="cover","apply forces cover in playback and editor");Assert((bool)theme.Json["UnknownVendorField"]["preserve"],"unknown fields survive native export/import");Assert(File.Exists(theme.Background),"package media resolves after import");Assert(theme.Texts.Count==1,"native text layer survives");
   using(var renderer=new ThemeRenderer(theme,90)){var jpeg=renderer.Compose(null,new SensorSnapshot(),80);using(var stream=new MemoryStream(jpeg))using(var bitmap=new Bitmap(stream))Assert(bitmap.Width==100&&bitmap.Height==320,"native portrait rotation");}
   string nativeFolder=Path.Combine(folder,"native"),sourceFolder=Path.Combine(nativeFolder,"source");Directory.CreateDirectory(sourceFolder);File.Copy(image,Path.Combine(sourceFolder,"d.png"));File.WriteAllText(Path.Combine(nativeFolder,"Setting.txt"),"name:Native image test\nwidth:320\nheight:100\nd.png:x@0,y@0,z@1,height@100,width@320\n");var nativeJson=ThemeDocument.Blank("Native image test",320,100);nativeJson["Type"]=1;nativeJson["DisplayTexts"]=new JArray(new JObject{{"TextType","DIYTextList"},{"Text","existing"},{"Top",1000}});string nativePath=Path.Combine(nativeFolder,"Native.json");AppPaths.SaveJson(nativePath,nativeJson);var nativeTheme=ThemeDocument.Load(nativePath);Assert(nativeTheme.Images.Count==1&&File.Exists((string)nativeTheme.Images[0]["Image"]),"native source PNG loads even when text layers were already saved");using(var nativeRenderer=new ThemeRenderer(nativeTheme,0)){var jpeg=nativeRenderer.Compose(null,new SensorSnapshot(),80);using(var stream=new MemoryStream(jpeg))using(var bitmap=new Bitmap(stream))Assert(bitmap.GetPixel(30,30).R>180,"native source PNG is composited on display");}
   string key="selftest-"+Guid.NewGuid().ToString("N");using(var store=new PreparedStore(key,4,24)){store.Add(new byte[]{1,2,3});store.Add(new byte[]{4,5,6});Assert(store.MemoryBytes<=4&&store.Read(1)[2]==6,"RAM cap spills to disk");store.Finish();}using(var store=new PreparedStore(key,4,24))Assert(store.Complete&&store.Count==2&&store.Read(0)[0]==1,"persistent cache reopens");foreach(string f in Directory.GetFiles(AppPaths.Data("Cache"),key+"*"))File.Delete(f);
   using(var engine=new PlaybackEngine(theme,new StudioSettings{Width=320,Height=100,Fps=60,Quality=75,CacheMB=32},false)){engine.Start();var timer=Stopwatch.StartNew();while(engine.Produced<100&&engine.Error.Length==0&&timer.ElapsedMilliseconds<5000)Thread.Sleep(20);Assert(engine.Produced>=100&&engine.Error.Length==0,"60 FPS cached playback without USB");}
   Console.WriteLine("PASS: native theme roundtrip, unknown fields, media, JPEG, rotation, bounded persistent cache and 60 FPS playback; no USB.");
  }finally{Directory.Delete(folder,true);if(imported!=null&&Path.GetFullPath(imported).StartsWith(Path.GetFullPath(AppPaths.Data("Themes"))+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))Directory.Delete(Path.GetDirectoryName(imported),true);}}
 }
}
